<template>
  <div style="width: 90%; max-width: 1200px; margin: 20px auto">
    <el-card>
      <div slot="header" style="display: flex; justify-content: space-between; align-items: center">
        <span>退款 / 售后申请</span>
      </div>

      <el-form label-width="90px">
        <el-form-item label="订单编号">
          <el-input v-model.trim="form.orderNo" maxlength="64"></el-input>
        </el-form-item>
        <el-form-item label="申请类型">
          <el-select v-model="form.type" placeholder="请选择" style="width: 200px">
            <el-option label="退款" value="退款"></el-option>
            <el-option label="售后" value="售后"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="申请原因">
          <el-input type="textarea" :rows="4" v-model.trim="form.reason" maxlength="2000" show-word-limit></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="success" @click="submit">提交申请</el-button>
          <el-button @click="resetForm">清空</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <el-card style="margin-top: 18px">
      <div slot="header" style="display: flex; justify-content: space-between; align-items: center">
        <span>我的申请</span>
      </div>

      <el-table :data="tableData" stripe style="width: 100%">
        <el-table-column prop="createTime" label="申请时间" width="170"></el-table-column>
        <el-table-column prop="orderNo" label="订单编号" width="200"></el-table-column>
        <el-table-column prop="type" label="类型" width="80"></el-table-column>
        <el-table-column prop="status" label="状态" width="100">
          <template slot-scope="scope">
            <el-tag v-if="scope.row.status === '待处理'" type="warning">待处理</el-tag>
            <el-tag v-else-if="scope.row.status === '已同意'" type="success">已同意</el-tag>
            <el-tag v-else type="info">已拒绝</el-tag>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="120">
          <template slot-scope="scope">
            <el-button type="text" @click="openDetail(scope.row.id)">详情</el-button>
          </template>
        </el-table-column>
      </el-table>

      <div style="padding: 15px 0; text-align: right">
        <el-pagination
          background
          layout="prev, pager, next"
          :current-page="pageNum"
          :page-size="pageSize"
          :total="total"
          @current-change="handlePageChange"
        ></el-pagination>
      </div>
    </el-card>

    <el-dialog title="申请详情" :visible.sync="detailVisible" width="700px">
      <div v-if="detail">
        <div style="margin-bottom: 10px"><b>订单编号：</b>{{ detail.orderNo }}</div>
        <div style="margin-bottom: 10px"><b>类型：</b>{{ detail.type }}</div>
        <div style="margin-bottom: 10px"><b>状态：</b>{{ detail.status }}</div>
        <div style="margin-bottom: 10px"><b>申请时间：</b>{{ detail.createTime }}</div>
        <div style="margin-bottom: 10px"><b>处理时间：</b>{{ detail.handleTime || '-' }}</div>
        <div style="margin-bottom: 10px"><b>原因：</b></div>
        <div style="white-space: pre-wrap">{{ detail.reason }}</div>
      </div>
      <span slot="footer" class="dialog-footer">
        <el-button @click="detailVisible = false">关闭</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: "AfterSale",
  data() {
    return {
      form: {
        orderNo: "",
        type: "",
        reason: "",
      },
      tableData: [],
      pageNum: 1,
      pageSize: 10,
      total: 0,
      detailVisible: false,
      detail: null,
    };
  },
  created() {
    this.form.orderNo = this.$route.query.orderNo || "";
    this.load();
  },
  methods: {
    resetForm() {
      this.form = { orderNo: this.$route.query.orderNo || "", type: "", reason: "" };
    },
    submit() {
      const orderNo = (this.form.orderNo || "").trim();
      const type = (this.form.type || "").trim();
      const reason = (this.form.reason || "").trim();
      if (!orderNo) {
        this.$message.error("订单编号不能为空");
        return;
      }
      if (!type) {
        this.$message.error("申请类型不能为空");
        return;
      }
      if (!reason) {
        this.$message.error("申请原因不能为空");
        return;
      }
      this.request.post("/api/afterSale", { orderNo, type, reason }).then((res) => {
        if (res.code === "200") {
          this.$message.success("提交成功");
          this.resetForm();
          this.pageNum = 1;
          this.load();
        } else {
          this.$message.error(res.msg || "提交失败");
        }
      });
    },
    load() {
      this.request
        .get("/api/afterSale/mine/page", {
          params: { pageNum: this.pageNum, pageSize: this.pageSize },
        })
        .then((res) => {
          if (res.code === "200") {
            this.tableData = res.data.records || [];
            this.total = res.data.total || 0;
          } else {
            this.$message.error(res.msg || "加载失败");
          }
        });
    },
    handlePageChange(page) {
      this.pageNum = page;
      this.load();
    },
    openDetail(id) {
      this.request.get("/api/afterSale/" + id).then((res) => {
        if (res.code === "200") {
          this.detail = res.data;
          this.detailVisible = true;
        } else {
          this.$message.error(res.msg || "加载失败");
        }
      });
    },
  },
};
</script>

